SELECT id, tenant_id, event_id, app_id, open_id, trigger_type, preset_id,
       registration_token_exp, message_id, status, skip_reason, errmsg, create_time
FROM crm_event_mp_outreach_log

    AND event_id = #{eventId}
    AND status = #{statusFilter}
    AND open_id = #{openId}

ORDER BY create_time DESC

SELECT open_id AS openId, app_id AS appId, MAX(create_time) AS sentAt FROM crm_event_mp_outreach_log WHERE event_id = #{eventId} AND status = 'sent' AND open_id IN
#{oid}
GROUP BY open_id, app_id
